const fs=require('node:fs'),path=require('node:path'),http=require('node:http'),assert=require('node:assert/strict');
const {chromium}=require('playwright');
const root=path.resolve(__dirname,'..'),map=require('../assets/catalog-photo-map.json');
const files=dir=>fs.readdirSync(dir,{withFileTypes:true}).flatMap(e=>e.isDirectory()?files(path.join(dir,e.name)):e.name.endsWith('.html')?[path.join(dir,e.name)]:[]);
const redirects=Object.fromEntries(fs.readFileSync(path.join(root,'_redirects'),'utf8').split(/\r?\n/).filter(line=>line.trim()&&!line.trim().startsWith('#')).map(line=>line.trim().split(/\s+/)).filter(row=>row.length===3&&/^30[12]$/.test(row[2])&&row[0].startsWith('/')&&row[1].startsWith('/')).map(([from,to])=>[decodeURI(from),decodeURI(to)]));
const server=http.createServer((req,res)=>{let file=path.resolve(root,'.'+decodeURI(new URL(req.url,'http://local').pathname));if(file!==root&&!file.startsWith(root+path.sep))return res.writeHead(403).end();if(fs.existsSync(file)&&fs.statSync(file).isDirectory())file=path.join(file,'index.html');if(!fs.existsSync(file))return res.writeHead(404).end();res.writeHead(200,{'Content-Type':({'.html':'text/html; charset=utf-8','.css':'text/css','.js':'application/javascript','.json':'application/json','.webp':'image/webp','.png':'image/png'})[path.extname(file)]||'application/octet-stream'});fs.createReadStream(file).pipe(res);});
async function run(){if(!process.env.TEST_ORIGIN)await new Promise(r=>server.listen(0,'127.0.0.1',r));const origin=process.env.TEST_ORIGIN||`http://127.0.0.1:${server.address().port}`,browser=await chromium.launch();try{const p=await browser.newPage(),covered=new Set(),output=path.resolve(root,'../4050-category-photos-20261102'+(process.env.TEST_ORIGIN?'-live':''));fs.mkdirSync(output,{recursive:true});await p.route('**/*',r=>r.request().url().startsWith(origin)?r.continue():r.abort());let lists=0,cards=0;
 for(const file of files(path.join(root,'category'))){const route='/'+path.relative(root,file).replaceAll(path.sep,'/').replace(/index\.html$/,'');const response=await p.goto(origin+route);assert.equal(response.status(),200,route);
  const rows=await p.locator('.post-card').evaluateAll((nodes,{redirects})=>nodes.map(card=>{const a=card.querySelector('h2 a'),im=card.querySelector('img');if(!a||!im)return null;let route=decodeURI(new URL(a.href).pathname),seen=new Set();while(redirects[route]&&!seen.has(route)){seen.add(route);route=redirects[route];}return {slug:route.split('/')[1],src:im.getAttribute('src'),srcset:im.getAttribute('srcset')||'',alt:im.alt,width:im.getAttribute('width'),height:im.getAttribute('height')};}).filter(Boolean),{redirects});
  if(rows.length)lists++;for(const row of rows){const photo=map[row.slug];assert.ok(photo,'Unmapped '+row.slug);assert.equal(row.src,photo.image);assert.equal(row.srcset,photo.srcset);assert.ok(row.alt.includes('AI'));assert.equal(row.width,'800');assert.equal(row.height,'500');covered.add(row.slug);cards++;}
 }
 for(const width of [1440,390,320])for(const category of ['license','support','rejob','money','welfare','grant']){await p.setViewportSize({width,height:900});await p.goto(origin+'/category/'+category+'/');for(const im of await p.locator('.post-card img').all()){await im.scrollIntoViewIfNeeded();await im.evaluate(n=>n.decode());assert.ok(await im.evaluate(n=>n.naturalWidth>0));}assert.equal(await p.evaluate(()=>document.documentElement.scrollWidth>innerWidth),false,category+' overflow '+width);await p.evaluate(()=>scrollTo(0,0));await p.screenshot({path:path.join(output,category+'-'+width+'.png')});}
 assert.equal(covered.size,215);const report={pass:true,origin,categoryLists:lists,categoryCards:cards,coveredArticles:covered.size,widths:[1440,390,320],allImagesDecoded:true,output};fs.writeFileSync(path.join(root,'reports/category-photos-qa'+(process.env.TEST_ORIGIN?'-live':'')+'-20261102.json'),JSON.stringify(report,null,2)+'\n');console.log(JSON.stringify(report));
 }finally{await browser.close();server.close();}}
run().catch(e=>{console.error(e);server.close();process.exitCode=1});
